  "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ==========================================\n// 1. User MODELS\n// ==========================================\nenum Role {\n  ADMIN\n  MANAGER\n  STAFF // Waiters, POS operators\n  KITCHEN // Chefs\n  CUSTOMER\n}\n\nmodel User {\n  id               String   @id @map(\"_id\")\n  name             String\n  email            String   @unique\n  emailVerified    Boolean  @default(false)\n  image            String?\n  twoFactorEnabled Boolean? @default(false)\n  displayUsername  String?\n  role             Role     @default(CUSTOMER)\n  status           String   @default(\"active\") // active, suspended, deleted\n  age              Int?\n  gender           String?\n  phone            String?\n  banned           Boolean  @default(false)\n  banReason        String?\n  stripeCustomerId String?\n\n  // Relations\n  sessions      Session[]\n  accounts      Account[]\n  twoFactors    TwoFactor[]\n  activitiesLog activitiesLog[]\n  feedbacks     Feedback[] // 👈 NEW: Relation to feedbacks\n  reservations  Reservation[] // 👈 NEW: Relation to reservations\n  orders        Order[] // 👈 NEW: Relation to orders\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n\n  @@map(\"user\")\n}\n\nmodel Session {\n  id        String   @id @map(\"_id\")\n  expiresAt DateTime\n  token     String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  ipAddress String?\n  userAgent String?\n\n  // Relations\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id @map(\"_id\")\n  accountId             String\n  providerId            String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  // Relations\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id @map(\"_id\")\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([identifier])\n  @@map(\"verification\")\n}\n\n// Optional: Two Factor Authentication plugin\n\nmodel TwoFactor {\n  id          String   @id @map(\"_id\")\n  secret      String\n  backupCodes String\n  verified    Boolean? @default(true)\n\n  // Relations\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([secret])\n  @@index([userId])\n  @@map(\"twoFactor\")\n}\n\n// ==========================================\n// 2. RESTAURANT BUSINESS MODELS\n// ==========================================\nmodel Category {\n  id   String @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name String @unique\n  // optional\n  slug String @unique\n\n  items menuItem[]\n}\n\nmodel activitiesLog {\n  id     String @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  action  String\n  details String?\n\n  createdAt DateTime @default(now())\n}\n\nmodel menuItem {\n  id           String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name         String\n  description  Json?\n  price        Float\n  discount     Float?   @default(0)\n  image        String?\n  isAvailable  Boolean  @default(true)\n  recipe       String?\n  categoryId   String   @db.ObjectId\n  category     Category @relation(fields: [categoryId], references: [id])\n  aiSuggestion String? // 👈 NEW: Stores Gemini's advice for bad reviews\n\n  feedbacks  Feedback[] // 👈 NEW: Relation to feedbacks\n  orderItems OrderItem[] // 👈 NEW: Relation to order items\n}\n\nmodel Feedback {\n  id         String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  rating     Int // 1 to 5 stars\n  comment    String?\n  menuItemId String   @db.ObjectId\n  menuItem   menuItem @relation(fields: [menuItemId], references: [id], onDelete: Cascade)\n  userId     String?\n  user       User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt  DateTime @default(now())\n}\n\nenum TableStatus {\n  AVAILABLE\n  OCCUPIED\n  RESERVED\n}\n\nenum TableType {\n  square\n  circle\n  rectangle\n}\n\nmodel Table {\n  id      String      @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name    String      @unique // e.g., \"05\", \"06\", \"VIP 1\"\n  seats   Int\n  section String      @default(\"Main Dining Room\") // Main Dining Room, Outdoor, Terrace\n  shape   TableType   @default(square) // square, circle, rectangle\n  status  TableStatus @default(AVAILABLE)\n\n  reservations Reservation[]\n  orders       Order[] // 👈 NEW: Relation to orders\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  CANCELLED\n  COMPLETED\n}\n\nmodel Reservation {\n  id           String        @id @default(auto()) @map(\"_id\") @db.ObjectId\n  customerName String? // Useful if guest booking\n  userId       String?\n  user         User?         @relation(fields: [userId], references: [id])\n  tableId      String        @db.ObjectId\n  table        Table         @relation(fields: [tableId], references: [id])\n  date         DateTime\n  guests       Int\n  status       BookingStatus @default(PENDING)\n}\n\nenum OrderType {\n  DINE_IN\n  TAKEAWAY\n  DELIVERY\n}\n\nenum OrderStatus {\n  PENDING\n  PREPARING\n  READY\n  SERVED\n  CANCELLED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n}\n\nenum PaymentMethod {\n  CASH\n  CARD\n  ONLINE\n}\n\nmodel Order {\n  id            String        @id @default(auto()) @map(\"_id\") @db.ObjectId\n  orderType     OrderType // DINE_IN, TAKEAWAY, DELIVERY\n  status        OrderStatus   @default(PENDING)\n  paymentStatus PaymentStatus @default(PENDING)\n  paymentMethod PaymentMethod @default(ONLINE)\n  totalAmount   Float\n\n  // Relations\n  userId  String?\n  user    User?   @relation(fields: [userId], references: [id])\n  tableId String? @db.ObjectId // Only for DINE_IN\n  table   Table?  @relation(fields: [tableId], references: [id])\n\n  items     OrderItem[]\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n}\n\nmodel OrderItem {\n  id         String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  orderId    String   @db.ObjectId\n  order      Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  menuItemId String   @db.ObjectId\n  menuItem   menuItem @relation(fields: [menuItemId], references: [id])\n  quantity   Int\n  price      Float // Snapshot of price at time of order\n  notes      String? // e.g., \"No onions\"\n}\n",
